using Alice.Actors;using Alice.Interaction;using Alice.Navigation;using Alice.Npc;using Alice.World;
namespace Alice.Perception;public static class PickupOpportunityObservationProjector{public static PickupOpportunityObservedReceipt ProjectObserved(ActorId actor,ActorVisibleTargetSpatialSnapshot target,PickupContract contract,WorldDrop drop){ActorIdentity.ValidateActorId(actor);ArgumentNullException.ThrowIfNull(target);ArgumentNullException.ThrowIfNull(contract);ArgumentNullException.ThrowIfNull(drop);if(target.TargetRef!=contract.ContractRef.TargetRef||target.Position!=drop.Position||contract.Version!=drop.Version||contract.AccessPolicy==PickupAccessPolicy.ClaimantOnly&&drop.ClaimantActorId!=actor)throw new ArgumentException();return new(target,new KnownPickupOpportunity(contract.ContractRef,contract.Version,contract.InteractionRange,new KnownCapabilityRequirement(contract.Requirement.CapabilityIdentity,contract.Requirement.MinimumValue),drop.DropId,drop.Items.Select(x=>new KnownDestructionYield(x.ItemTypeId,x.Quantity))));}public static PickupOpportunityUnavailableReceipt ProjectUnavailable(ContractRef contractRef,long version)=>new(contractRef,version);}
